"""`.Expression`: generated by export_nodes.py from library.blend; kept by hand from then on."""

NAME = '.Expression'
KIND = 'ShaderNodeTree'


def build(lib):
    t = lib.new_group(NAME, KIND, props={})

    t.socket('OUTPUT', 'Shader', 'NodeSocketShader')
    t.socket('INPUT', 'Choice', 'NodeSocketFloat', default_value=2.0, min_value=0.0, max_value=2.0)
    t.socket('INPUT', 'Shader', 'NodeSocketShader')
    t.socket('INPUT', 'Color 1', 'NodeSocketColor')
    t.socket('INPUT', 'Alpha 1', 'NodeSocketFloat')
    t.socket('INPUT', 'Color 2', 'NodeSocketColor')
    t.socket('INPUT', 'Alpha 2', 'NodeSocketFloat')

    t.node('ShaderNodeMath', 'Math', inputs={'Value_001': 1.0}, props={
        'location': (-57.888, 89.16223),
        'hide': True,
        'operation': 'SUBTRACT',
        'use_clamp': True,
    })
    t.node('ShaderNodeMix', 'Mix', inputs={'Factor_Float': 0.5}, props={
        'location': (-56.239277, 14.714245),
        'hide': True,
        'data_type': 'RGBA',
    })
    t.node('ShaderNodeMix', 'Mix.001', inputs={'Factor_Float': 0.5}, props={
        'location': (-55.62193, -62.18361),
        'hide': True,
    })
    t.node('ShaderNodeMix', 'Mix.003', inputs={'Factor_Float': 0.5}, props={
        'location': (134.75676, -61.470375),
        'hide': True,
    })
    t.node('ShaderNodeMixShader', 'Mix Shader', props={
        'location': (447.61285, 118.60399),
    })
    t.node('NodeGroupOutput', 'Group Output', props={
        'location': (641.6374, 118.694046),
    })
    t.node('NodeGroupInput', 'Group Input', props={
        'location': (-660.9459, 122.3394),
    })

    t.link('Math', 'Value', 'Mix.003', 'Factor_Float')
    t.link('Mix.001', 'Result_Float', 'Mix.003', 'A_Float')
    t.link('Mix.003', 'Result_Float', 'Mix Shader', 'Fac')
    t.link('Group Input', 'Shader', 'Mix Shader', 'Shader')
    t.link('Mix Shader', 'Shader', 'Group Output', 'Shader')
    t.link('Group Input', 'Choice', 'Math', 'Value')
    t.link('Group Input', 'Choice', 'Mix', 'Factor_Float')
    t.link('Group Input', 'Choice', 'Mix.001', 'Factor_Float')
    t.link('Mix', 'Result_Color', 'Mix Shader', 'Shader_001')
    t.link('Group Input', 'Color 1', 'Mix', 'A_Color')
    t.link('Group Input', 'Alpha 1', 'Mix.001', 'A_Float')
    t.link('Group Input', 'Color 2', 'Mix', 'B_Color')
    t.link('Group Input', 'Alpha 2', 'Mix.001', 'B_Float')
    return t
